import { setupBrowserRuntime } from "../../browser/browser-client.mjs";

export { setupBrowserRuntime };

export async function getBrowser(family = "chrome") {
  const agent = await setupBrowserRuntime({ environment: "codex-app" });
  const browsers = await agent.browsers.list();
  const target = browsers.find(b => b.family === family || b.name.toLowerCase().includes(family));
  if (!target) {
    throw new Error(`Browser '${family}' is not connected. Connected browsers: ${browsers.map(b => b.name).join(", ") || "none"}`);
  }
  return await agent.browsers.get(target.id);
}

export default { setupBrowserRuntime, getBrowser };
